UPDATE products SET description='لون صغير يغيّر مزاج يومكِ. أضيفي لمسة لون أنيقة إلى يديك مع طلاء الأظافر من آيس. اختيار بسيط لتجديد المانيكير في المنزل، سواء أحببتِ إطلالة يومية هادئة أو لونًا يرافق مناسباتك. حدّدي الدرجة التي تناسبك عند اعتماد التشكيلة.',details_json='{"nameAr":"طلاء أظافر آيس","tagline":"تفصيلة صغيرة تغيّر مزاج إطلالتك.","benefits":["لون يكمّل إطلالتك","تجديد سهل للمانيكير","مناسب لتنسيق ألوانك المفضلة"],"howToUse":"ضعي طبقات رقيقة على أظافر نظيفة وجافة، واتركي كل طبقة تجف قبل التالية.","notes":"اختاري الدرجة المتاحة؛ صور الألوان لا تغني عن تحديد اسم الدرجة.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"nails","en":{"name":"ICE · Nail Polish","tagline":"A little colour for your everyday mood.","description":"ICE · Nail Polish. A little colour for your everyday mood. Choose a small moment of beauty that fits the way you like to get ready.","benefits":["A little colour for your everyday mood.","A dedicated step to coordinate with your existing routine."],"howToUse":"Follow the exact product’s instructions on clean, dry nails. Allow each layer to dry before the next.","notes":"Gel colour may require an appropriate lamp. Check the product type before use and avoid the surrounding skin.","variantNote":""},"contentVersion":"3.0.0"}',category='المكياج',subcategory='أظافر',updated_at=datetime('now') WHERE id='TS0001' AND description='أضيفي لمسة لون أنيقة إلى يديك مع طلاء الأظافر من آيس. اختيار بسيط لتجديد المانيكير في المنزل، سواء أحببتِ إطلالة يومية هادئة أو لونًا يرافق مناسباتك. حدّدي الدرجة التي تناسبك عند اعتماد التشكيلة.' AND details_json='{"nameAr": "طلاء أظافر آيس", "tagline": "تفصيلة صغيرة تغيّر مزاج إطلالتك.", "benefits": ["لون يكمّل إطلالتك", "تجديد سهل للمانيكير", "مناسب لتنسيق ألوانك المفضلة"], "howToUse": "ضعي طبقات رقيقة على أظافر نظيفة وجافة، واتركي كل طبقة تجف قبل التالية.", "notes": "اختاري الدرجة المتاحة؛ صور الألوان لا تغني عن تحديد اسم الدرجة.", "imageType": "photo", "collection": "beauty", "featuredOrd