UPDATE products SET description='لحظة لون أو عناية، لكِ وحدكِ. لمسة جيلي لامعة تمنح الشفاه مظهرًا حيويًا وتتيح لك تنويع الإطلالة بسهولة. تضم المجموعة خيارات لتنسيق اللمعة مع المكياج اليومي أو فوق لون شفاهك المفضل، لتختاري اللمسة التي تناسب مزاجك.',details_json='{"nameAr":"مجموعة جلوس جيلي للشفاه من أوليبولا","tagline":"لمعان مرح يضيف الحياة إلى ابتسامتك.","benefits":["مظهر لامع للشفاه","تنويع الإطلالة اليومية","يمكن تنسيقه مع لون شفاه آخر"],"howToUse":"مرري كمية خفيفة على الشفاه ووزعيها بالتساوي، منفردة أو فوق أحمر الشفاه.","notes":"تُحدّد ألوان المجموعة وعدد القطع بحسب العبوة المعتمدة.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"lips","en":{"name":"OLIBOLLA · Jelly Lip Gloss Set","tagline":"A little moment for your lips.","description":"OLIBOLLA · Jelly Lip Gloss Set. A little moment for your lips. Keep your favourite lip detail close, from an everyday moment to evening plans.","benefits":["A little moment for your lips.","Make the finish your own, one light layer at a time."],"howToUse":"Apply gently to clean lips as directed on the packaging. Start with a little and add more if needed.","notes":"Choose the available colour or version. Do not share lip products, and stop use if irritation occurs.","variantNote":""},"contentVersion":"3.0.0"}',category='المكياج',subcategory='شفاه',updated_at=datetime('now') WHERE id='TS0003' AND description='لمسة جيلي لامعة تمنح الشفاه مظهرًا حيويًا وتتيح لك تنويع الإطلالة بسهولة. تضم المجموعة خيارات لتنسيق اللمعة مع المكياج اليومي أو فوق لون شفاهك المفضل، لتختاري اللمسة التي تناسب مزاجك.' AND details_json='{"nameAr": "مجموعة جلوس جيلي للشفاه من أوليبولا", "tagline": "لمعان مرح يضيف الحياة إلى ابتسامتك.", "benefits": ["مظهر لامع للشفاه", "تنويع الإطلالة اليومية", "يمكن تنسيقه مع لون شفاه آخر"], "howToUse": "مرري كمية خفيفة على الشفاه ووزعيها بالتساوي، منفردة أو فوق أحمر الشفاه.", "notes": "تُحدّد ألوان المجموعة وعدد القطع بحسب العبوة المعتمدة.", "imageType": "photo", "collection": "beauty", "feature