UPDATE products SET description='خطوة نهارية تستحق مكانًا في روتينكِ. أضيفي إلى صباحك واقيًا من خط أويل كنترول عندما تريدين حماية يومية مع اهتمام بمظهر اللمعان. صُممت هذه المجموعة لتلائم روتين البشرة الدهنية أو المختلطة، مع ضرورة اختيار النسخة الفعلية ودرجة الحماية المناسبة.',details_json='{"nameAr":"واقي الشمس أويل كنترول من يوسيرين","tagline":"حماية تناسب الإطلالة الأقل لمعانًا.","benefits":["خطوة حماية نهارية","اهتمام بمظهر اللمعان","مناسب لروتين البشرة الدهنية"],"howToUse":"وزعي كمية كافية وفق العبوة وجددي أثناء التعرض للشمس، خاصة بعد التعرق أو السباحة.","notes":"تُحدد النسخة ودرجة SPF والحجم عند اعتماد المنتج.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"sunscreen","en":{"name":"Eucerin Oil Control Sunscreen","tagline":"Make room for a daily sun-care ritual.","description":"Eucerin Oil Control Sunscreen. Make room for a daily sun-care ritual. Give sun care a regular place at the end of your morning skincare, before makeup.","benefits":["Make room for a daily sun-care ritual.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply generously and evenly as the final step of morning skincare, before sun exposure. Reapply as directed, especially after sweating or swimming.","notes":"Check the SPF and directions on your exact pack. Use shade and protective clothing as well; no sunscreen blocks all UV exposure.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='واقي شمس',updated_at=datetime('now') WHERE id='TS0031' AND description='أضيفي إلى صباحك واقيًا من خط أويل كنترول عندما تريدين حماية يومية مع اهتمام بمظهر اللمعان. صُممت هذه المجموعة لتلائم روتين البشرة الدهنية أو المختلطة، مع ضرورة اختيار النسخة الفعلية ودرجة الحماية المناسبة.' AND details_json='{"nameAr": "واقي الشمس أويل كنترول من يوسيرين", "tagline": "حماية تناسب الإطلالة الأقل لمعانًا.", "benefits": ["خطوة حماية نهارية", "اهتمام بمظهر اللمعان", "مناسب لروتين البشرة الدهنية"], "howToUse": "وزعي كمية كافية وفق العبوة وجددي أثناء التعرض للشمس، خاصة بعد التعرق أو السباحة.", "notes": "تُحدد النسخة ودرجة SPF والحجم عند اعتماد المنتج.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}' AND category='البشرة' AND subcategory='واقي شمس';
UPDATE products SET description='تسريحة على مزاجكِ، بلمستكِ. تجمع هذه المجموعة خطوات مخصصة لمظهر الشعر والرموش والحواجب لتختاري لكل منطقة عنايتها المناسبة. هي خيار لمن تحب تنسيق الروتين، مع الحفاظ على الفصل بين مستحضر فروة الرأس والمستحضر المخصص لمنطقة العين.',details_json='{"nameAr":"مجموعة عناية الشعر والرموش والحواجب من ذا أورديناري","tagline":"عناية منظمة بأكثر من تفصيلة.","benefits":["تنظيم خطوات العناية","منتجات لمناطق مختلفة","مجموعة بدل شراء القطع منفردة"],"howToUse":"استخدمي كل قطعة في المنطقة والطريقة المحددتين عليها، دون نقل مستحضر الشعر إلى العين.","notes":"يجب اعتماد مكونات المجموعة وعدد القطع والأحجام قبل عرضها للبيع.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"hair-styling","en":{"name":"The Ordinary Hair, Lash & Brow Care Set","tagline":"Your hair, styled your way.","description":"The Ordinary Hair, Lash & Brow Care Set. Your hair, styled your way. Choose a small moment of beauty that fits the way you like to get ready.","benefits":["Your hair, styled your way.","A dedicated step to coordinate with your existing routine."],"howToUse":"Work a small amount through the specified areas and shape gently, following the exact product’s instructions.","notes":"Avoid eyes and inhaling powders or sprays. Wash out as directed.","variantNote":""},"contentVersion":"3.0.0"}',category='الشعر',subcategory='مجموعات',updated_at=datetime('now') WHERE id='TS0032' AND description='تجمع هذه المجموعة خطوات مخصصة لمظهر الشعر والرموش والحواجب لتختاري لكل منطقة عنايتها المناسبة. هي خيار لمن تحب تنسيق الروتين، مع الحفاظ على الفصل بين مستحضر فروة الرأس والمستحضر المخصص لمنطقة العين.' AND details_json='{"nameAr": "مجموعة عناية الشعر والرموش والحواجب من ذا أورديناري", "tagline": "عناية منظمة بأكثر من تفصيلة.", "benefits": ["تنظيم خطوات العناية", "منتجات لمناطق مختلفة", "مجموعة بدل شراء القطع منفردة"], "howToUse": "استخدمي كل قطعة في المنطقة والطريقة المحددتين عليها، دون نقل مستحضر الشعر إلى العين.", "notes": "يجب اعتماد مكونات المجموعة وعدد القطع