UPDATE products SET description='ختام خفيف لروتين مكياجكِ. أكملي المكياج برذاذ يساعد على توحيد مظهر طبقاته ومنح الإطلالة لمسة نهائية مرتبة. يناسب من تحب إضافة خطوة تثبيت بعد البودرة أو الفاونديشن، مع اختيار القوام الذي ينسجم مع نوع بشرتها.',details_json='{"nameAr":"بخاخ تثبيت المكياج من دكتور راشيل","tagline":"اللمسة الأخيرة بعد إتمام إطلالتك.","benefits":["إنهاء خطوات المكياج","تلطيف مظهر الطبقات","توزيع برذاذ خفيف"],"howToUse":"رشي بالمسافة المحددة على العبوة بعد المكياج مع إغلاق العينين والفم، واتركيه يجف.","notes":"لا يرش داخل العين ولا يستخدم على جلد متهيج.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"setting-spray","en":{"name":"Dr Rashel Makeup Setting Spray","tagline":"A finishing moment for your makeup.","description":"Dr Rashel Makeup Setting Spray. A finishing moment for your makeup. Choose a small moment of beauty that fits the way you like to get ready.","benefits":["A finishing moment for your makeup.","A dedicated step to coordinate with your existing routine."],"howToUse":"Close your eyes and mouth and mist from the distance stated on the packaging.","notes":"Do not inhale the spray. Follow the packaging directions and avoid spraying into the eyes.","variantNote":""},"contentVersion":"3.0.0"}',category='المكياج',subcategory='مثبت المكياج',updated_at=datetime('now') WHERE id='TS0033' AND description='أكملي المكياج برذاذ يساعد على توحيد مظهر طبقاته ومنح الإطلالة لمسة نهائية مرتبة. يناسب من تحب إضافة خطوة تثبيت بعد البودرة أو الفاونديشن، مع اختيار القوام الذي ينسجم مع نوع بشرتها.' AND details_json='{"nameAr": "بخاخ تثبيت المكياج من دكتور راشيل", "tagline": "اللمسة الأخيرة بعد إتمام إطلالتك.", "benefits": ["إنهاء خطوات المكياج", "تلطيف مظهر الطبقات", "توزيع برذاذ خفيف"], "howToUse": "رشي بالمسافة المحددة على العبوة بعد المكياج مع إغلاق العينين والفم، واتركيه يجف.", "notes": "لا يرش داخل العين ولا يستخدم على جلد متهيج.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}' AND category='المكياج' AND subcategory='مكياج الوجه';
