UPDATE products SET description='هناك خطوات صغيرة نحب العودة إليها آخر اليوم. كريم 345 ريليف من دكتور ألثيا يمنح خطوة الترطيب مكانها الخاص في روتينكِ؛ وزّعي كمية مناسبة بعد السيروم، وخذي وقتكِ في تطبيقها بلطف. اختاريه وفق احتياج بشرتكِ، وجرّبيه على مساحة صغيرة أولًا.',details_json='{"nameAr":"كريم 345 ريليف من دكتور ألثيا","tagline":"اجعلي الترطيب لحظة تعودين إليها.","benefits":["ترطيب يومي","دعم حاجز الترطيب","تلطيف مظهر الجفاف"],"howToUse":"وزعي كمية مناسبة على الوجه بعد السيروم، صباحًا أو مساءً بحسب احتياج البشرة.","notes":"لا تستخدميه على تهيج مستمر دون معرفة سببه.","imageType":"photo","collection":"k-beauty","featuredOrder":0,"productType":"moisturizer","en":{"name":"Dr. Althea - 345 Relief Cream","tagline":"A moisturising moment to come back to.","description":"Some little rituals are worth returning to at the end of the day. Give your moisturising step its own moment with Dr. Althea 345 Relief Cream. Apply gently after serum, take your time, and patch test before making it a regular part of your routine.","benefits":["Make your moisturising moment something to enjoy.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply a suitable amount to clean skin and massage gently. Follow the frequency and areas of use on the pack.","notes":"Patch test first. Stop use if irritation occurs and avoid contact with the eyes.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='مرطب',updated_at=datetime('now') WHERE id='TS0059' AND description='حين تحتاج بشرتك إلى مرطب يمنحها إحساسًا بالراحة، يأتي 345 ريليف بقوام يسهل دمجه في الروتين. يساعد على تلطيف مظهر الجفاف ويدعم حاجز الترطيب، لتبدو البشرة أنعم وأكثر توازنًا خلال يومك.' AND details_json='{"nameAr": "كريم 345 ريليف من دكتور ألثيا", "tagline": "راحة الترطيب بخطوة كورية خفيفة.", "benefits": ["ترطيب يومي", "دعم حاجز الترطيب", "تلطيف مظهر الجفاف"], "howToUse": "وزعي كمية مناسبة على الوجه بعد السيروم، صباحًا أو مساءً بحسب احتياج البشرة.", "notes": "لا تستخدميه على تهيج مستمر 