UPDATE products SET description='اختاري وقتًا قصيرًا للعناية، بعيدًا عن استعجال اليوم. سيروم دارك سبوت كوريكتنغ غلو من أكسيس واي خطوة يمكن تنسيقها مع المرطب وواقي الشمس لروتين مدروس. ابدئي تدريجيًا، فالعناية المنتظمة ألطف من الوعود السريعة، وتجربة كل بشرة مختلفة.',details_json='{"nameAr":"سيروم دارك سبوت غلو من أكسيس واي","tagline":"روتينكِ المنتظم يبدأ بخطوة تحبّينها.","benefits":["العناية بمظهر الآثار","إشراقة أكثر تجانسًا","إحساس بالترطيب"],"howToUse":"وزعي كمية صغيرة على الوجه أو المناطق المطلوبة بعد التنظيف، ثم أكملي المرطب.","notes":"النتائج تختلف، والحماية من الشمس جزء من روتين العناية بالآثار.","imageType":"photo","collection":"k-beauty","featuredOrder":2,"productType":"serum","en":{"name":"Axis-Y Dark Spot Correcting Glow Serum","tagline":"A thoughtful little step, at your own pace.","description":"Make a little space for care beyond the rush of your day. AXIS-Y Dark Spot Correcting Glow Serum can sit alongside your moisturiser and daytime sunscreen in a considered routine. Introduce it gradually: every skin experience is different, and there are no instant-result promises.","benefits":["A thoughtful step in a routine that is yours.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply a small amount to clean skin as directed on the exact product, then follow with moisturiser. Introduce one new active product at a time.","notes":"Patch test first. Results vary by skin and routine; this product is not a substitute for medical advice.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='سيروم',updated_at=datetime('now') WHERE id='TS0067' AND description='اختيار لمن تريد عناية يومية بمظهر تفاوت اللون وآثار الشوائب. يساعد سيروم أكسيس واي على إضافة خطوة موجهة إلى النضارة، بقوام يمكنك تنسيقه مع المرطب وواقي الشمس ضمن روتين منتظم.' AND details_json='{"nameAr": "سيروم دارك سبوت كوريكتنغ من أكسيس واي", "tagline": "اهتمام بمظهر الآثار مع لمسة ترطيب.", "benefits": ["العناية بمظهر الآثار", "إشراقة أكثر تجانسًا", "إحساس بالترطيب"], "howToUse": "وزعي كمية صغيرة على الوجه أو المناطق المطلوبة بعد التنظيف، ثم أكملي المرطب.", "notes": "النتائج تختلف، والحماية من الشمس جزء من روتين العناية بالآثار.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 2}' AND category='البشرة' AND subcategory='سيروم';
UPDATE products SET description='لمسة عناية لأكثر تفاصيل وجهكِ رقة. امنحي منطقة تحت العين وقت عناية مريحًا مع باتشات أبيب الجيلية. تساعد على تلطيف مظهر الجفاف والخطوط الناتجة عنه، وتضيف إلى روتينك خطوة خاصة عندما ترغبين بمظهر أكثر نعومة وانتعاشًا.',details_json='{"nameAr":"باتشات غلو جيلي للعين من أبيب","tagline":"استراحة ترطيب لمحيط العين.","benefits":["ترطيب لمحيط العين","قوام جيلي مريح","تحسين مظهر الجفاف"],"howToUse":"ثبتي الباتشات في المكان المخصص للمدة المدونة على العبوة، ثم أزيليها بلطف.","notes":"تحتوي هذه النسخة على ريتينال؛ اتّبعي تواتر العبوة وتجنبي التهيج والعين نفسها.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"eye-care","en":{"name":"Abib - PDRN Retinal Eye Patch Glow Jelly","tagline":"A small, careful moment for your eyes.","description":"Abib - PDRN Retinal Eye Patch Glow Jelly. A small, careful moment for your eyes. Choose a small moment of beauty that fits the way you like to get ready.","benefits":["A small, careful moment for your eyes.","A dedicated step to coordinate with your existing routine."],"howToUse":"Use a very small amount in the area indicated on the pack, with gentle application and no pulling.","notes":"Keep out of the eyes. Lash products and eye creams have different directions; follow your exact product’s label. Introduce gradually and follow the exact retinoid directions. Check suitability with a qualified professional if pregnant or breastfeeding.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='العين',updated_at=datetime('now') WHERE id='TS0068' AND description='امنحي منطقة تحت العين وقت عناية مريحًا مع باتشات أبيب الجيلية. تساعد على تلطيف مظهر الجفاف والخطوط الناتجة عنه، وتضيف إلى روتينك خطوة خاصة عندما ترغبين بمظهر أكثر نعومة وانتعاشًا.' AND details_json='{"nameAr": "باتشات غلو جيلي للعين من أبيب", "tagline": "استراحة ترطيب لمحيط العين.", "benefits": ["ترطيب لمحيط العين", "قوام جيلي مريح", "تحسين مظهر الجفاف"], "howToUse": "ثبتي الباتشات في المكان المخصص للمدة ال