UPDATE products SET description='خطوة تختارينها على مزاج بشرتكِ. أضيفي إلى روتينك خطوة موجهة إلى البهتان وتفاوت مظهر اللون مع بوستر أرينسيا. يمنحك قوام سيروم يسهل توزيعه قبل المرطب، لتكملي العناية بتركيز أكبر على النضارة بدل الاكتفاء بالترطيب وحده.',details_json='{"nameAr":"فيتامين سي بوستر شوت من أرينسيا","tagline":"عناية بإشراقة تبدو أكثر حيوية.","benefits":["العناية بمظهر البهتان","دعم مظهر الإشراقة","خطوة سيروم قبل الكريم"],"howToUse":"ضعي كمية صغيرة بعد التنظيف وفق تعليمات النسخة المتاحة.","notes":"اختبريه على مساحة صغيرة واستكملي الحماية من الشمس نهارًا.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"serum","en":{"name":"Arencia - Vitamin C Booster Shot","tagline":"A thoughtful step in a routine that is yours.","description":"Arencia - Vitamin C Booster Shot. A thoughtful step in a routine that is yours. Choose this step to suit your own skin and routine, introducing it gradually.","benefits":["A thoughtful step in a routine that is yours.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply a small amount to clean skin as directed on the exact product, then follow with moisturiser. Introduce one new active product at a time.","notes":"Patch test first. Results vary by skin and routine; this product is not a substitute for medical advice.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='سيروم',updated_at=datetime('now') WHERE id='TS0069' AND description='أضيفي إلى روتينك خطوة موجهة إلى البهتان وتفاوت مظهر اللون مع بوستر أرينسيا. يمنحك قوام سيروم يسهل توزيعه قبل المرطب، لتكملي العناية بتركيز أكبر على النضارة بدل الاكتفاء بالترطيب وحده.' AND details_json='{"nameAr": "فيتامين سي بوستر شوت من أرينسيا", "tagline": "عناية بإشراقة تبدو أكثر حيوية.", "benefits": ["العناية بمظهر البهتان", "دعم مظهر الإشراقة", "خطوة سيروم قبل الكريم"], "howToUse": "ضعي كمية صغيرة بعد التنظيف وفق تعليمات النسخة المتاحة.", "notes": "اختبريه على مساحة صغيرة واستكملي الحماية من الشمس نهارًا.", "imageTyp