UPDATE products SET description='خطوة تختارينها على مزاج بشرتكِ. عندما يبدو لون البشرة غير متجانس أو تظهر عليها علامات الانزعاج، يضيف هذا السيروم خطوة عناية موجهة مع إحساس بالترطيب. اختاري روتينًا بسيطًا حوله وأدخليه تدريجيًا لتراقبي ملاءمته لبشرتك.',details_json='{"nameAr":"سيروم أزيليك هايالورون من أنوا","tagline":"عناية بمظهر الاحمرار والملمس.","benefits":["العناية بمظهر الاحمرار","إحساس بالترطيب","تحسين مظهر تفاوت الملمس"],"howToUse":"وزعي كمية صغيرة على بشرة سليمة وفق إرشادات العبوة، ثم أتبعيها بمرطب.","notes":"لا يقدّم علاجًا لتشخيصات جلدية، وتوقفي عند استمرار التهيج.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"serum","en":{"name":"Anua - Azelaic Acid 10 Hyaluron Redness Soothing Serum","tagline":"A thoughtful step in a routine that is yours.","description":"Anua - Azelaic Acid 10 Hyaluron Redness Soothing Serum. A thoughtful step in a routine that is yours. Choose this step to suit your own skin and routine, introducing it gradually.","benefits":["A thoughtful step in a routine that is yours.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply a small amount to clean skin as directed on the exact product, then follow with moisturiser. Introduce one new active product at a time.","notes":"Patch test first. Results vary by skin and routine; this product is not a substitute for medical advice.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='سيروم',updated_at=datetime('now') WHERE id='TS0071' AND description='عندما يبدو لون البشرة غير متجانس أو تظهر عليها علامات الانزعاج، يضيف هذا السيروم خطوة عناية موجهة مع إحساس بالترطيب. اختاري روتينًا بسيطًا حوله وأدخليه تدريجيًا لتراقبي ملاءمته لبشرتك.' AND details_json='{"nameAr": "سيروم أزيليك هايالورون من أنوا", "tagline": "عناية بمظهر الاحمرار والملمس.", "benefits": ["العناية بمظهر الاحمرار", "إحساس بالترطيب", "تحسين مظهر تفاوت الملمس"], "howToUse": "وزعي كمية صغيرة على بشرة سليمة وفق إرشادات العبوة، ثم أتبعيها بمرطب.", "notes":