UPDATE products SET description='خطوة تختارينها على مزاج بشرتكِ. أضيفي إلى العناية الكورية خطوة تركز على مظهر البهتان والآثار. أمبول تون برايتننغ يمنحك قوامًا يسهل توزيعه قبل الكريم، ليساعد البشرة على الظهور بنضارة أكثر تجانسًا ضمن روتين منتظم.',details_json='{"nameAr":"أمبول تون برايتننغ من سكين 1004","tagline":"عناية بإشراقة البشرة وتجانس مظهرها.","benefits":["العناية بمظهر تفاوت اللون","إحساس بالترطيب","خطوة أمبول سهلة الدمج"],"howToUse":"وزعي كمية مناسبة بعد التونر إن استخدمته وقبل المرطب.","notes":"استكملي الحماية من الشمس؛ النسخة المرجعية في القائمة 50 مل.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"serum","en":{"name":"SKIN1004 – Madagascar Centella Tone Brightening Capsule Ampoule (50ml)","tagline":"A thoughtful step in a routine that is yours.","description":"SKIN1004 – Madagascar Centella Tone Brightening Capsule Ampoule (50ml). A thoughtful step in a routine that is yours. Choose this step to suit your own skin and routine, introducing it gradually.","benefits":["A thoughtful step in a routine that is yours.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply a small amount to clean skin as directed on the exact product, then follow with moisturiser. Introduce one new active product at a time.","notes":"Patch test first. Results vary by skin and routine; this product is not a substitute for medical advice.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='سيروم',updated_at=datetime('now') WHERE id='TS0078' AND description='أضيفي إلى العناية الكورية خطوة تركز على مظهر البهتان والآثار. أمبول تون برايتننغ يمنحك قوامًا يسهل توزيعه قبل الكريم، ليساعد البشرة على الظهور بنضارة أكثر تجانسًا ضمن روتين منتظم.' AND details_json='{"nameAr":"أمبول تون برايتننغ من سكين 1004","tagline":"عناية بإشراقة البشرة وتجانس مظهرها.","benefits":["العناية بمظهر تفاوت اللون","إحساس بالترطيب","خطوة أمبول سهلة الدمج"],"howToUse":"وزعي كمية مناسبة بعد التونر إن استخدمته وقبل المرطب.","notes":"اس