UPDATE products SET description='بين تنظيف بشرتكِ وترطيبها، امنحي نفسكِ لحظة هادئة مع إيسنس سنيل 96 من كوسركس. ضعي كمية صغيرة واربتي بلطف قبل الكريم؛ خطوة يسهل أن تصبح جزءًا من روتينكِ الصباحي أو المسائي، من دون تحويل العناية إلى مهمة طويلة.',details_json='{"nameAr":"إيسنس سنيل 96 من كوسركس","tagline":"طبقة ترطيب، ولحظة لكِ وحدكِ.","benefits":["إحساس بالترطيب","ملمس أكثر نعومة","تهيئة البشرة للكريم"],"howToUse":"وزعي كمية صغيرة بعد التنظيف والتونر إن استخدمته، ثم أتبعيها بمرطب.","notes":"اختبريه موضعيًا عند الحساسية من مستحضرات الحلزون.","imageType":"photo","collection":"k-beauty","featuredOrder":1,"productType":"essence","en":{"name":"COSRX – Advanced Snail 96 Mucin Power Essence","tagline":"A little layer of care, just for you.","description":"Make a quiet moment between cleansing and moisturising with COSRX Advanced Snail 96 Mucin Power Essence. Pat on a little after toner and before your cream. It is a simple way to give your skincare ritual a moment of its own, morning or evening.","benefits":["A little layer of care to look forward to.","A dedicated step to coordinate with your existing routine."],"howToUse":"Pat a small amount onto clean skin after toner and before moisturiser, following the pack directions.","notes":"Patch test before regular use and stop if irritation occurs.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='الإيسنس',updated_at=datetime('now') WHERE id='TS0079' AND description='حين تبدو البشرة باهتة أو مشدودة بعد الغسل، يضيف إيسنس سنيل خطوة ترطيب بقوامه الانسيابي المميز. يساعد على تنعيم مظهر الملمس وتهيئة البشرة للكريم، ليصبح روتينك أكثر راحة قبل المكياج أو في المساء.' AND details_json='{"nameAr": "إيسنس سنيل 96 من كوسركس", "tagline": "ترطيب يمنح الملمس مظهرًا ممتلئًا بالحيوية.", "benefits": ["إحساس بالترطيب", "ملمس أكثر نعومة", "تهيئة البشرة للكريم"], "howToUse": "وزعي كمية صغيرة بعد التنظيف والتونر إن استخدمته، ثم أتبعيها بمرطب.", "notes": "اختبريه موضعيًا عند الحساسية من مستحضرات الحلزون.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 1}' AND category='المكياج' AND subcategory='إيسنس';
UPDATE products SET description='أكملي طبقات عنايتكِ بكريم سنيل 92 أول إن ون من كوسركس. بعد التنظيف والسيروم، وزّعي كمية مناسبة بلطف وخذي لحظتكِ بعيدًا عن استعجال اليوم. خطوة ترطيب يمكنكِ تنسيقها مع إيسنس سنيل 96 أو روتينكِ المعتاد بحسب ما يلائم بشرتكِ.',details_json='{"nameAr":"كريم سنيل 92 أول إن ون من كوسركس","tagline":"آخر طبقة عناية، وأجمل وقت لنفسكِ.","benefits":["تلطيف مظهر الجفاف","إحساس بالنعومة","خطوة كريم بعد السيروم"],"howToUse":"وزعي كمية مناسبة بعد خطوات العناية الأخف، ثم ربتي بلطف حتى يتوزع.","notes":"يختلف عن إيسنس سنيل 96؛ أحدهما إيسنس والآخر كريم.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"moisturizer","en":{"name":"COSRX – Advanced Snail 92 All In One Cream","tagline":"A final layer of care, a little time for you.","description":"Finish your skincare layers with COSRX Advanced Snail 92 All In One Cream. Apply a suitable amount gently after cleansing and serum. Pair it with Snail 96 Essence or your existing routine according to what suits your skin.","benefits":["Make your moisturising moment something to enjoy.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply a suitable amount to clean skin and massage gently. Follow the frequency and areas of use on the pack.","notes":"Patch test first. Stop use if irritation occurs and avoid contact with the eyes.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='المرطبات والكريمات',updated_at=datetime('now') WHERE id='TS0080' AND description='امنحي بشرتك خطوة كريم من مجموعة سنيل للعناية بمظهر الجفاف والملمس. قوامه المميز يوزع بكمية صغيرة، ويكمل الإيسنس أو السيروم عندما تريدين طبقة ترطيب تساعد الوجه على الظهور أكثر راحة وحيوية.' AND details_json='{"nameAr": "كريم سنيل 92 من كوسركس", "tagline": "كريم يكمل إحساس النعومة والترطيب.", "benefits": ["تلطيف مظهر الجفاف", "إحساس بالنعومة", "خطوة كريم بعد السيروم"], "howToUse": "وزعي كمية مناسبة بعد خطوات العناية الأخف، ثم ربتي بلطف حتى يتوزع.", "notes": "يختلف عن إيسنس سنيل 96؛ أحدهما إيسنس والآخر كريم.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}' AND category='المكياج' AND subcategory='مرطب';
UPDATE products SET description='خطوة نهارية تستحق مكانًا في روتينكِ. إذا كنتِ تفضلين قوامًا أخف في روتين النهار، تعرفي إلى نسخة أكوا فريش من ريليف صن. تمنحك خطوة حماية سهلة التوزيع، ويمكن تنسيقها مع المرطب والمكياج دون إهمال الكمية والتجديد.',details_json='{"nameAr":"واقي ريليف صن أكوا فريش من بيوتي أوف جوسون","tagline":"حماية بخفة تناسب صباحك.","benefits":["حماية نهارية","قوام خفيف","سهولة تنسيقه مع روتين الصباح"],"howToUse":"طبقي كمية كافية وفق العبوة وجددي أثناء التعرض للشمس.","notes":"نسخة Aqua Fresh مستقلة عن ريليف صن الأصلي وليست تكرارًا له.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"sunscreen","en":{"name":"Beauty of joseon - Relief Sun Aqua Fresh","tagline":"Make room for a daily sun-care ritual.","description":"Beauty of joseon - Relief Sun Aqua Fresh. Make room for a daily sun-care ritual. Give sun care a regular place at the end of your morning skincare, before makeup.","benefits":["Make room for a daily sun-care ritual.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply generously and evenly as the final step of morning skincare, before sun exposure. Reapply as directed, especially after sweating or swimming.","notes":"Check the SPF and directions on your exact pack. Use shade and protective clothing as well; no sunscreen blocks all UV exposure.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='واقي شمس',updated_at=datetime('now') WHERE id='TS0081' AND description='إذا كنتِ تفضلين قوامًا أخف في روتين النهار، تعرفي إلى نسخة أكوا فريش من ريليف صن. تمنحك خطوة حماية سهلة التوزيع، ويمكن تنسيقها مع المرطب والمكياج دون إهمال الكمية والتجديد.' AND details_json='{"nameAr": "واقي ريليف صن أكوا فريش من بيوتي أوف جوسون", "tagline": "حماية بخفة تناسب صباحك.", "benefits": ["حماية نهارية", "قوام خفيف", "سهولة تنسيقه مع روتين الصباح"], "howToUse": "طبقي كمية كافية وفق العبوة وجددي أثناء التعرض للشمس.", "notes": "نسخة Aqua Fresh مستقلة عن ريليف صن الأصلي وليست تكرارًا له.", "im