UPDATE products SET description='لمسة عناية لأكثر تفاصيل وجهكِ رقة. خصصي لمحيط العين خطوة تهتم بمظهر البهتان مع الترطيب. يمنحك كريم ماري آند ماي عناية سهلة التوزيع حول المنطقة الرقيقة، لتكملي روتين الوجه بلمسة تركز على النعومة وإطلالة أكثر انتعاشًا.',details_json='{"nameAr":"كريم العين ترانكساميك وغلوتاثيون من ماري آند ماي","tagline":"عناية بإشراقة منطقة تحت العين.","benefits":["ترطيب محيط العين","العناية بمظهر البهتان","ملمس أنعم تحت المكياج"],"howToUse":"ربتي بكمية صغيرة حول عظمة العين دون شد الجلد أو إدخاله إلى العين.","notes":"لا يعالج كل أسباب الهالات، واختبري ملاءمته لبشرتك.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"eye-care","en":{"name":"Mary & May – Tranexamic Acid + Glutathione Eye Cream","tagline":"A small, careful moment for your eyes.","description":"Mary & May – Tranexamic Acid + Glutathione Eye Cream. A small, careful moment for your eyes. Choose a small moment of beauty that fits the way you like to get ready.","benefits":["A small, careful moment for your eyes.","A dedicated step to coordinate with your existing routine."],"howToUse":"Use a very small amount in the area indicated on the pack, with gentle application and no pulling.","notes":"Keep out of the eyes. Lash products and eye creams have different directions; follow your exact product’s label.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='العين',updated_at=datetime('now') WHERE id='TS0082' AND description='خصصي لمحيط العين خطوة تهتم بمظهر البهتان مع الترطيب. يمنحك كريم ماري آند ماي عناية سهلة التوزيع حول المنطقة الرقيقة، لتكملي روتين الوجه بلمسة تركز على النعومة وإطلالة أكثر انتعاشًا.' AND details_json='{"nameAr": "كريم العين ترانكساميك وغلوتاثيون من ماري آند ماي", "tagline": "عناية بإشراقة منطقة تحت العين.", "benefits": ["ترطيب محيط العين", "العناية بمظهر البهتان", "ملمس أنعم تحت المكياج"], "howToUse": "ربتي بكمية صغيرة حول عظمة العين دون شد الجلد أو إدخاله إلى العين.", "notes": "لا يعالج كل أسباب الهالات، واختبري ملاءمته لبشرتك.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}' AND category='البشرة' AND subcategory='العين';
UPDATE products SET description='اجعلي وقت الترطيب لحظتكِ المفضلة. امنحي البشرة إحساسًا نديًا مع كريم الكولاجين الجيلي من ميديكيوب. يوزع بسهولة كخطوة ترطيب بعد السيرومات، ويساعد على تحسين مظهر الجفاف ليصبح الوجه أكثر نعومة وحيوية في روتينك المعتاد.',details_json='{"nameAr":"كريم كولاجين جيلي من ميديكيوب","tagline":"ترطيب بقوام جيلي ينعش روتينك.","benefits":["إحساس ندي بالترطيب","قوام جيلي","تلطيف مظهر الجفاف"],"howToUse":"وزعي كمية مناسبة على الوجه بعد السيروم وربتي حتى يتوزع.","notes":"ابدئي بكمية خفيفة إذا كانت بشرتك تميل إلى اللمعان.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"moisturizer","en":{"name":"medicube - Collagen Jelly Cream (110ml)","tagline":"Make your moisturising moment something to enjoy.","description":"medicube - Collagen Jelly Cream (110ml). Make your moisturising moment something to enjoy. Take a little time for gentle application, after your chosen skincare steps.","benefits":["Make your moisturising moment something to enjoy.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply a suitable amount to clean skin and massage gently. Follow the frequency and areas of use on the pack.","notes":"Patch test first. Stop use if irritation occurs and avoid contact with the eyes.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='مرطب',updated_at=datetime('now') WHERE id='TS0083' AND description='امنحي البشرة إحساسًا نديًا مع كريم الكولاجين الجيلي من ميديكيوب. يوزع بسهولة كخطوة ترطيب بعد السيرومات، ويساعد على تحسين مظهر الجفاف ليصبح الوجه أكثر نعومة وحيوية في روتينك المعتاد.' AND details_json='{"nameAr": "كريم كولاجين جيلي من ميديكيوب", "tagline": "ترطيب بقوام جيلي ينعش روتينك.", "benefits": ["إحساس ندي بالترطيب", "قوام جيلي", "تلطيف مظهر الجفاف"], "howToUse": "وزعي كمية مناسبة على الوجه بعد السيروم وربتي حتى يتوزع.", "notes": "ابدئي بكمية خفيفة إذا كانت بشرتك تميل إلى اللمعان.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}' AND category='ال