UPDATE products SET description='اجعلي واقي هيالو سيكا ووتر فيت من سكين 1004 جزءًا من استعدادكِ ليومكِ، من مشوار سريع إلى يوم مليء بالتفاصيل. اختاريه كخطوة أخيرة للعناية الصباحية، ثم ضعي مكياجكِ إن أحببتِ. راجعي تعليمات العبوة والتزمي بتجديد الحماية خلال اليوم.',details_json='{"nameAr":"واقي هيالو سيكا ووتر فيت من سكين 1004","tagline":"حماية النهار، ضمن روتين تحبّينه.","benefits":["حماية نهارية","قوام سيروم","إحساس مرطب قبل المكياج"],"howToUse":"وزعي كمية كافية حسب العبوة وجددي الحماية خلال التعرض وبعد التعرق أو السباحة.","notes":"لا تكفي طبقة قليلة جدًا لتحقيق الحماية المدونة على العبوة.","imageType":"photo","collection":"k-beauty","featuredOrder":5,"productType":"sunscreen","en":{"name":"SKIN1004 – Madagascar Centella Hyalu-Cica Water-Fit Sun Serum","tagline":"Make sun care part of a routine you enjoy.","description":"Bring SKIN1004 Hyalu-Cica Water-Fit Sun Serum into your getting-ready ritual, whether your day is busy or beautifully simple. Apply as the last skincare step before makeup, and follow the directions on your exact pack for quantity and reapplication.","benefits":["Make room for a daily sun-care ritual.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply generously and evenly as the final step of morning skincare, before sun exposure. Reapply as directed, especially after sweating or swimming.","notes":"Check the SPF and directions on your exact pack. Use shade and protective clothing as well; no sunscreen blocks all UV exposure.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='واقي شمس',updated_at=datetime('now') WHERE id='TS0085' AND description='أضيفي إلى صباحك واقيًا يجمع خطوة الحماية مع إحساس بالعناية المرطبة. نسخة هيالو سيكا ووتر فيت تليق بمن تفضل قوام السيروم سهل التوزيع قبل المكياج، مع الاهتمام بالتجديد عند التعرض للشمس.' AND details_json='{"nameAr": "واقي هيالو سيكا ووتر فيت من سكين 1004", "tagline": "حماية بقوام سيروم خفيف.", "benefits": ["حماية نهارية", "قوام سيروم", "إحساس مرطب قبل ال