UPDATE products SET description='أغلقي يومكِ بلحظة انتعاش. امنحي روتين البشرة الدهنية خطوة تنظيف موجهة إلى الدهون والشوائب اليومية. يكوّن غسول كوسركس رغوة تنظف السطح وتكمل العناية بمظهر المسام، مع أهمية مراقبة الجفاف واستكمال مرطب مناسب.',details_json='{"nameAr":"غسول ساليسيليك ديلي جنتل من كوسركس","tagline":"تنظيف للبشرة المعرضة لانسداد المسام.","benefits":["تنظيف دهون السطح","عناية بمظهر المسام","خطوة رغوية قبل العناية"],"howToUse":"رغّي كمية صغيرة على الوجه المبلل ثم اشطفي جيدًا دون فرك قوي.","notes":"يحتوي على مستحضر تقشيري؛ خففي التكرار إذا شعرتِ بالشد أو التهيج.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"cleanser","en":{"name":"COSRX - Salicylic Acid Daily Gentle Cleanser","tagline":"A fresh start, or a gentle end to your day.","description":"COSRX - Salicylic Acid Daily Gentle Cleanser. A fresh start, or a gentle end to your day. Make cleansing the first step of a little time for yourself.","benefits":["A fresh start, or a gentle end to your day.","A dedicated step to coordinate with your existing routine."],"howToUse":"Follow the instructions for this cleanser’s format. Massage gently without rubbing hard, and rinse or wipe off as its label directs.","notes":"Avoid contact with the eyes unless the exact product is labelled for eye makeup removal. Patch test and stop if irritation occurs.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='غسول',updated_at=datetime('now') WHERE id='TS0086' AND description='امنحي روتين البشرة الدهنية خطوة تنظيف موجهة إلى الدهون والشوائب اليومية. يكوّن غسول كوسركس رغوة تنظف السطح وتكمل العناية بمظهر المسام، مع أهمية مراقبة الجفاف واستكمال مرطب مناسب.' AND details_json='{"nameAr": "غسول ساليسيليك ديلي جنتل من كوسركس", "tagline": "تنظيف للبشرة المعرضة لانسداد المسام.", "benefits": ["تنظيف دهون السطح", "عناية بمظهر المسام", "خطوة رغوية قبل العناية"], "howToUse": "رغّي كمية صغيرة على الوجه المبلل ثم اشطفي جيدًا دون فرك قوي.", "notes": "يحتوي على مستحضر تقشيري؛ خففي التكر