UPDATE products SET description='بعد التنظيف، خذي استراحة صغيرة مع تونر هارتليف 77 من أنوا. وزّعيه براحة اليد أو بقطنة بلطف، ثم أكملي بالسيروم أو المرطب الذي يناسبكِ. لحظة بسيطة تجعل روتينكِ أقرب لوقت تحبّينه لنفسكِ.',details_json='{"nameAr":"تونر هارتليف 77 من أنوا","tagline":"بداية هادئة لطبقات عنايتكِ.","benefits":["عناية خفيفة بعد التنظيف","إحساس بالترطيب","تهيئة البشرة للسيروم"],"howToUse":"وزعيه براحة اليد أو بقطنة ناعمة وربتي بلطف، ثم أكملي خطوات العناية.","notes":"يمكن الاكتفاء بطبقة خفيفة؛ زيادة الطبقات ليست ضرورية للجميع.","imageType":"photo","collection":"k-beauty","featuredOrder":4,"productType":"toner","en":{"name":"Anua - Heartleaf 77% Soothing Toner","tagline":"A quiet start to your next layer of care.","description":"Take a small pause after cleansing with Anua Heartleaf 77% Soothing Toner. Apply gently with your palms or a cotton pad, then continue with your chosen serum or moisturiser. A simple moment to make your routine feel more like time for yourself.","benefits":["A quiet little pause between cleansing and care.","A dedicated step to coordinate with your existing routine."],"howToUse":"After cleansing, apply gently using your palms or a cotton pad, as directed on the pack. Follow with moisturiser.","notes":"Patch test first. If the toner contains exfoliating acids, introduce gradually and use sunscreen in the daytime.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='تونر',updated_at=datetime('now') WHERE id='TS0091' AND description='امنحي البشرة بعد الغسل طبقة عناية خفيفة تساعد على تلطيف إحساس الجفاف. تونر هارتليف يليق بروتين الطبقات الكورية البسيط، قبل السيروم والمرطب، عندما ترغبين بإحساس أكثر انتعاشًا وراحة.' AND details_json='{"nameAr":"تونر هارتليف 77 من أنوا","tagline":"خطوة سائلة تمنح روتينك بداية مريحة.","benefits":["عناية خفيفة بعد التنظيف","إحساس بالترطيب","تهيئة البشرة للسيروم"],"howToUse":"وزعيه براحة اليد أو بقطنة ناعمة وربتي بلطف، ثم أكملي خطوات العناية.","notes":"يمكن الاكتفاء بطبقة خفيفة؛ زيادة الطبقات ليست ضرورية للجميع.","imageType":"photo","collection":"k-beauty","featuredOrder":4,"productType":"toner"}' AND category='البشرة' AND subcategory='تونر';
UPDATE products SET description='خطوة تختارينها على مزاج بشرتكِ. أضيفي إلى الروتين سيرومًا يهتم بمظهر البشرة المرهقة والجافة. يساعد هذا الاختيار من أنوا على منح إحساس بالترطيب وتحسين مظهر الملمس، لتكملي العناية بطبقة خفيفة قبل الكريم.',details_json='{"nameAr":"سيروم PDRN هايالورونيك كابسول 100 من أنوا","tagline":"ترطيب يركز على نضارة المظهر.","benefits":["إحساس بالترطيب","مظهر أكثر حيوية","تكملة لروتين النضارة"],"howToUse":"وزعي كمية مناسبة على بشرة نظيفة قبل المرطب بحسب تعليمات العبوة.","notes":"لا يقدّم نتيجة فورية مضمونة؛ اختاريه بحسب ملاءمته لبشرتك.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"serum","en":{"name":"Anua - PDRN Hyaluronic Acid Capsule 100 Serum","tagline":"A thoughtful step in a routine that is yours.","description":"Anua - PDRN Hyaluronic Acid Capsule 100 Serum. A thoughtful step in a routine that is yours. Choose this step to suit your own skin and routine, introducing it gradually.","benefits":["A thoughtful step in a routine that is yours.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply a small amount to clean skin as directed on the exact product, then follow with moisturiser. Introduce one new active product at a time.","notes":"Patch test first. Results vary by skin and routine; this product is not a substitute for medical advice.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='سيروم',updated_at=datetime('now') WHERE id='TS0092' AND description='أضيفي إلى الروتين سيرومًا يهتم بمظهر البشرة المرهقة والجافة. يساعد هذا الاختيار من أنوا على منح إحساس بالترطيب وتحسين مظهر الملمس، لتكملي العناية بطبقة خفيفة قبل الكريم.' AND details_json='{"nameAr": "سيروم PDRN هايالورونيك كابسول 100 من أنوا", "tagline": "ترطيب يركز على نضارة المظهر.", "benefits": ["إحساس بالترطيب", "مظهر أكثر حيوية", "تكملة لروتين النضارة"], "howToUse": "وزعي كمية مناسبة على بشرة نظيفة قبل المرطب بحسب تعليمات العبوة.", "notes": "لا يقدّم نتيجة فورية مضمونة؛ اختاريه بحسب ملاءمته لبشرتك.