UPDATE products SET description='استراحة جمال على إيقاعكِ. أضيفي جلسة ماسك تهتم بمظهر دهون السطح والملمس غير المتجانس. ماسك ريد بين يكمّل الغسول والترطيب بخطوة متباعدة، ويمنحك إحساسًا بالنظافة عندما تريدين تدليل بشرتك دون روتين طويل.',details_json='{"nameAr":"ماسك ريد بين للمسام من بيوتي أوف جوسون","tagline":"استراحة عناية لملمس يبدو أكثر نقاءً.","benefits":["العناية بدهون السطح","تحسين مظهر الملمس","جلسة ماسك منزلية"],"howToUse":"وزعي على بشرة نظيفة بالطريقة والمدة المحددتين على العبوة ثم اشطفي بلطف.","notes":"لا تتركيه مدة أطول على أمل نتيجة أسرع، وتجنبي الجلد المتهيج.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"face-mask","en":{"name":"Beauty of Joseon - Red Bean Refreshing Pore Mask","tagline":"A little beauty pause, at your own pace.","description":"Beauty of Joseon - Red Bean Refreshing Pore Mask. A little beauty pause, at your own pace. Choose a small moment of beauty that fits the way you like to get ready.","benefits":["A little beauty pause, at your own pace.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply to clean skin for the time specified on the exact pack. Remove, rinse or leave on only as directed for that mask.","notes":"Avoid the eyes and broken skin. Patch test first; do not exceed the labelled contact time.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='ماسك',updated_at=datetime('now') WHERE id='TS0100' AND description='أضيفي جلسة ماسك تهتم بمظهر دهون السطح والملمس غير المتجانس. ماسك ريد بين يكمّل الغسول والترطيب بخطوة متباعدة، ويمنحك إحساسًا بالنظافة عندما تريدين تدليل بشرتك دون روتين طويل.' AND details_json='{"nameAr": "ماسك ريد بين للمسام من بيوتي أوف جوسون", "tagline": "استراحة عناية لملمس يبدو أكثر نقاءً.", "benefits": ["العناية بدهون السطح", "تحسين مظهر الملمس", "جلسة ماسك منزلية"], "howToUse": "وزعي على بشرة نظيفة بالطريقة والمدة المحددتين على العبوة ثم اشطفي بلطف.", "notes": "لا تتركيه مدة أطول على أمل نتيجة أسرع، وتجنبي الجلد المتهيج.", "im