UPDATE products SET description='خطوة نهارية تستحق مكانًا في روتينكِ. احملي خطوة الحماية المفضلة لديك بحجم أصغر، مناسب لتجربة قوام ريليف صن أو وضعه في حقيبة اليوم. تبقى طريقة الاستخدام والكمية الكافية مهمة كما في العبوة الكبيرة، حتى عند استخدام حجم السفر.',details_json='{"nameAr":"واقي ريليف صن بالحجم المصغّر من بيوتي أوف جوسون","tagline":"رفيق صغير لتجربة روتينك وحقيبتك.","benefits":["عبوة صغيرة للحقيبة","تجربة قوام المنتج","سهولة اصطحاب الواقي"],"howToUse":"وزعي كمية كافية وفق العبوة وجددي عند التعرض للشمس.","notes":"الحجم المصغر خيار مختلف عن العبوة الكبيرة ولا يعني استخدام كمية أقل لكل تطبيق.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"sunscreen","en":{"name":"Beauty of Joseon - Relief Sun Mini","tagline":"Make room for a daily sun-care ritual.","description":"Beauty of Joseon - Relief Sun Mini. Make room for a daily sun-care ritual. Give sun care a regular place at the end of your morning skincare, before makeup.","benefits":["Make room for a daily sun-care ritual.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply generously and evenly as the final step of morning skincare, before sun exposure. Reapply as directed, especially after sweating or swimming.","notes":"Check the SPF and directions on your exact pack. Use shade and protective clothing as well; no sunscreen blocks all UV exposure.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='واقي شمس',updated_at=datetime('now') WHERE id='TS0101' AND description='احملي خطوة الحماية المفضلة لديك بحجم أصغر، مناسب لتجربة قوام ريليف صن أو وضعه في حقيبة اليوم. تبقى طريقة الاستخدام والكمية الكافية مهمة كما في العبوة الكبيرة، حتى عند استخدام حجم السفر.' AND details_json='{"nameAr": "واقي ريليف صن بالحجم المصغّر من بيوتي أوف جوسون", "tagline": "رفيق صغير لتجربة روتينك وحقيبتك.", "benefits": ["عبوة صغيرة للحقيبة", "تجربة قوام المنتج", "سهولة اصطحاب الواقي"], "howToUse": "وزعي كمية كافية وفق العبوة وجددي عند التعرض للشمس.", "notes":