UPDATE products SET description='اجعلي وقت الترطيب لحظتكِ المفضلة. امنحي البشرة خطوة ترطيب لا تبدأ بقوام كريم كثيف. جل كريم بورمايزنغ لايت يليق بروتين يركز على إحساس الانتعاش ومظهر المسام، مع توزيع كمية مناسبة على المناطق التي تحتاج ترطيبًا.',details_json='{"nameAr":"جل كريم بورمايزنغ لايت من سكين 1004","tagline":"ترطيب خفيف للبشرة التي تفضل قوام الجل.","benefits":["قوام جل خفيف","إحساس منعش","ترطيب مناسب لطبقات العناية"],"howToUse":"وزعي كمية مناسبة بعد السيروم وربتي حتى يتوزع المستحضر.","notes":"يمكن زيادة العناية بالمناطق الأكثر جفافًا بمرطب يناسبها.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"moisturizer","en":{"name":"SKIN1004 · Centella Poremizing Light Gel Cream","tagline":"Make your moisturising moment something to enjoy.","description":"SKIN1004 · Centella Poremizing Light Gel Cream. Make your moisturising moment something to enjoy. Take a little time for gentle application, after your chosen skincare steps.","benefits":["Make your moisturising moment something to enjoy.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply a suitable amount to clean skin and massage gently. Follow the frequency and areas of use on the pack.","notes":"Patch test first. Stop use if irritation occurs and avoid contact with the eyes.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='مرطب',updated_at=datetime('now') WHERE id='TS0102' AND description='امنحي البشرة خطوة ترطيب لا تبدأ بقوام كريم كثيف. جل كريم بورمايزنغ لايت يليق بروتين يركز على إحساس الانتعاش ومظهر المسام، مع توزيع كمية مناسبة على المناطق التي تحتاج ترطيبًا.' AND details_json='{"nameAr": "جل كريم بورمايزنغ لايت من سكين 1004", "tagline": "ترطيب خفيف للبشرة التي تفضل قوام الجل.", "benefits": ["قوام جل خفيف", "إحساس منعش", "ترطيب مناسب لطبقات العناية"], "howToUse": "وزعي كمية مناسبة بعد السيروم وربتي حتى يتوزع المستحضر.", "notes": "يمكن زيادة العناية بالمناطق الأكثر جفافًا بمرطب يناسبها.", "imageType": "photo", "collection": "k-