UPDATE products SET description='اجعلي وقت الترطيب لحظتكِ المفضلة. أكملي العناية بكريم يركز على إحساس البشرة بالراحة وتلطيف مظهر الجفاف. سنتيلا سوذينغ يضيف طبقة ترطيب بعد السيروم، ويناسب من تبحث عن روتين بسيط يراعي حاجز البشرة ونعومة ملمسها.',details_json='{"nameAr":"كريم سنتيلا سوذينغ من سكين 1004","tagline":"راحة ترطيب بخطوة هادئة.","benefits":["إحساس بالترطيب","تلطيف مظهر الجفاف","تكملة لروتين بسيط"],"howToUse":"وزعي كمية مناسبة على بشرة نظيفة بعد الخطوات الأخف قوامًا.","notes":"توقفي عند ظهور تحسس؛ كلمة مهدئ لا تعني أنه يناسب الجميع.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"moisturizer","en":{"name":"SKIN1004 · Centella Soothing Cream","tagline":"Make your moisturising moment something to enjoy.","description":"SKIN1004 · Centella Soothing Cream. Make your moisturising moment something to enjoy. Take a little time for gentle application, after your chosen skincare steps.","benefits":["Make your moisturising moment something to enjoy.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply a suitable amount to clean skin and massage gently. Follow the frequency and areas of use on the pack.","notes":"Patch test first. Stop use if irritation occurs and avoid contact with the eyes.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='مرطب',updated_at=datetime('now') WHERE id='TS0103' AND description='أكملي العناية بكريم يركز على إحساس البشرة بالراحة وتلطيف مظهر الجفاف. سنتيلا سوذينغ يضيف طبقة ترطيب بعد السيروم، ويناسب من تبحث عن روتين بسيط يراعي حاجز البشرة ونعومة ملمسها.' AND details_json='{"nameAr": "كريم سنتيلا سوذينغ من سكين 1004", "tagline": "راحة ترطيب بخطوة هادئة.", "benefits": ["إحساس بالترطيب", "تلطيف مظهر الجفاف", "تكملة لروتين بسيط"], "howToUse": "وزعي كمية مناسبة على بشرة نظيفة بعد الخطوات الأخف قوامًا.", "notes": "توقفي عند ظهور تحسس؛ كلمة مهدئ لا تعني أنه يناسب الجميع.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}' AND category='البشرة' AN