UPDATE products SET description='مساحة هادئة بين التنظيف والعناية. امنحي روتينك خطوة تونر موجهة إلى بهتان البشرة وتراكم شوائب السطح. يساعد هذا الاختيار من كوسركس على تحسين مظهر الملمس ضمن استخدام متدرج، مع الاحتفاظ بالترطيب جزءًا أساسيًا من العناية.',details_json='{"nameAr":"تونر AHA/BHA كلاريفاينغ من كوسركس","tagline":"عناية خفيفة بمظهر السطح والمسام.","benefits":["العناية بمظهر الملمس","تحسين مظهر البهتان","خطوة تونر سهلة"],"howToUse":"وزعي بالطريقة والتواتر المدونين على العبوة، بعيدًا عن العينين.","notes":"يحتوي على أحماض تقشير؛ لا تكثري المقشرات واستخدمي واقي شمس.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"toner","en":{"name":"COSRX - AHA/BHA Clarifying Treatment Toner","tagline":"A quiet little pause between cleansing and care.","description":"COSRX - AHA/BHA Clarifying Treatment Toner. A quiet little pause between cleansing and care. Take a pause after cleansing before your next layer of care.","benefits":["A quiet little pause between cleansing and care.","A dedicated step to coordinate with your existing routine."],"howToUse":"After cleansing, apply gently using your palms or a cotton pad, as directed on the pack. Follow with moisturiser.","notes":"Patch test first. If the toner contains exfoliating acids, introduce gradually and use sunscreen in the daytime.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='تونر',updated_at=datetime('now') WHERE id='TS0105' AND description='امنحي روتينك خطوة تونر موجهة إلى بهتان البشرة وتراكم شوائب السطح. يساعد هذا الاختيار من كوسركس على تحسين مظهر الملمس ضمن استخدام متدرج، مع الاحتفاظ بالترطيب جزءًا أساسيًا من العناية.' AND details_json='{"nameAr": "تونر AHA/BHA كلاريفاينغ من كوسركس", "tagline": "عناية خفيفة بمظهر السطح والمسام.", "benefits": ["العناية بمظهر الملمس", "تحسين مظهر البهتان", "خطوة تونر سهلة"], "howToUse": "وزعي بالطريقة والتواتر المدونين على العبوة، بعيدًا عن العينين.", "notes": "يحتوي على أحماض تقشير؛ لا تكثري المقشرات واستخدمي واقي شمس.", "imag