UPDATE products SET description='اكتشفي روتينكِ، خطوة بخطوة. تعرفي إلى مجموعة سنيل من خلال أحجام تجريبية تساعدك على فهم القوام وترتيب خطوات العناية قبل اختيار عبوات أكبر. تتيح المجموعة تنسيق العناية بالوجه ومحيط العين بحسب القطع الفعلية الموجودة فيها.',details_json='{"nameAr":"مجموعة سنيل التجريبية من كوسركس","tagline":"اكتشفي روتين سنيل بخطوات صغيرة.","benefits":["تجربة أكثر من قوام","أحجام عملية","تنسيق خطوات روتين سنيل"],"howToUse":"اتبعي تعليمات كل قطعة وترتيب استخدامها المرفق بالمجموعة.","notes":"تُراجع محتويات المجموعة وأحجامها عند اعتماد العبوة.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"skincare-set","en":{"name":"COSRX - All About Snail Trial Kit","tagline":"Explore your next ritual, one step at a time.","description":"COSRX - All About Snail Trial Kit. Explore your next ritual, one step at a time. Choose a small moment of beauty that fits the way you like to get ready.","benefits":["Explore your next ritual, one step at a time.","A dedicated step to coordinate with your existing routine."],"howToUse":"Check the directions for each item in the set and introduce new products gradually rather than all at once.","notes":"Set contents and sizes should be checked against the available pack. Patch test each new product.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='مجموعات العناية',updated_at=datetime('now') WHERE id='TS0106' AND description='تعرفي إلى مجموعة سنيل من خلال أحجام تجريبية تساعدك على فهم القوام وترتيب خطوات العناية قبل اختيار عبوات أكبر. تتيح المجموعة تنسيق العناية بالوجه ومحيط العين بحسب القطع الفعلية الموجودة فيها.' AND details_json='{"nameAr": "مجموعة سنيل التجريبية من كوسركس", "tagline": "اكتشفي روتين سنيل بخطوات صغيرة.", "benefits": ["تجربة أكثر من قوام", "أحجام عملية", "تنسيق خطوات روتين سنيل"], "howToUse": "اتبعي تعليمات كل قطعة وترتيب استخدامها المرفق بالمجموعة.", "notes": "تُراجع محتويات المجموعة وأحجامها عند اعتماد العبوة.", "imageType": "photo", "collection": "k-beauty", "