UPDATE products SET description='لحظة لون أو عناية، لكِ وحدكِ. امنحي الشفاه عناية أعمق من لمسة بلسم سريعة مع ماسك ليب باتر. قوامه المريح يضيف طبقة عناية إلى روتين المساء، ليساعد على تلطيف مظهر الجفاف وتهيئة الشفاه لإطلالة أجمل في اليوم التالي.',details_json='{"nameAr":"ماسك الشفاه الليلي بالسيراميد من كوسركس","tagline":"راحة ترطيب لشفاه تبدو أكثر نعومة.","benefits":["تلطيف مظهر الجفاف","إحساس مريح بالترطيب","خطوة عناية مسائية"],"howToUse":"وزعي كمية مناسبة على شفاه نظيفة وفق تعليمات العبوة.","notes":"لا تضعيه داخل الفم، وتجنبي استخدامه فوق تهيج غير معروف السبب.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"lips","en":{"name":"COSRX - Balancium Ceramide Lip Butter Sleeping Mask","tagline":"A little moment for your lips.","description":"COSRX - Balancium Ceramide Lip Butter Sleeping Mask. A little moment for your lips. Keep your favourite lip detail close, from an everyday moment to evening plans.","benefits":["A little moment for your lips.","Make the finish your own, one light layer at a time."],"howToUse":"Apply gently to clean lips as directed on the packaging. Start with a little and add more if needed.","notes":"Choose the available colour or version. Do not share lip products, and stop use if irritation occurs.","variantNote":""},"contentVersion":"3.0.0"}',category='المكياج',subcategory='شفاه',updated_at=datetime('now') WHERE id='TS0107' AND description='امنحي الشفاه عناية أعمق من لمسة بلسم سريعة مع ماسك ليب باتر. قوامه المريح يضيف طبقة عناية إلى روتين المساء، ليساعد على تلطيف مظهر الجفاف وتهيئة الشفاه لإطلالة أجمل في اليوم التالي.' AND details_json='{"nameAr": "ماسك الشفاه الليلي بالسيراميد من كوسركس", "tagline": "راحة ترطيب لشفاه تبدو أكثر نعومة.", "benefits": ["تلطيف مظهر الجفاف", "إحساس مريح بالترطيب", "خطوة عناية مسائية"], "howToUse": "وزعي كمية مناسبة على شفاه نظيفة وفق تعليمات العبوة.", "notes": "لا تضعيه داخل الفم، وتجنبي استخدامه فوق تهيج غير معروف السبب.", "imageType": "photo", "collection": "k-beauty", "featuredOrder