UPDATE products SET description='لحظة لون أو عناية، لكِ وحدكِ. أضيفي إلى المساء طبقة عناية تمنح شفاهك إحساسًا أكثر راحة. ماسك بروبوليس للشفاه يركز على مظهر الجفاف والنعومة، ويمكن أن يكون خطوة خاصة قبل النوم لمن تحتاج شفاهها اهتمامًا إضافيًا.',details_json='{"nameAr":"ماسك الشفاه الليلي بالبروبوليس من كوسركس","tagline":"لحظة تدليل لنعومة الابتسامة.","benefits":["إحساس بالترطيب","ملمس أنعم","عناية ضمن روتين الليل"],"howToUse":"وزعي على شفاه نظيفة بالطريقة المحددة على العبوة.","notes":"اختبريه أولًا عند الحساسية من منتجات النحل.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"lips","en":{"name":"COSRX - Full Fit Propolis Lip Sleeping Mask","tagline":"A little moment for your lips.","description":"COSRX - Full Fit Propolis Lip Sleeping Mask. A little moment for your lips. Keep your favourite lip detail close, from an everyday moment to evening plans.","benefits":["A little moment for your lips.","Make the finish your own, one light layer at a time."],"howToUse":"Apply gently to clean lips as directed on the packaging. Start with a little and add more if needed.","notes":"Choose the available colour or version. Do not share lip products, and stop use if irritation occurs.","variantNote":""},"contentVersion":"3.0.0"}',category='المكياج',subcategory='شفاه',updated_at=datetime('now') WHERE id='TS0108' AND description='أضيفي إلى المساء طبقة عناية تمنح شفاهك إحساسًا أكثر راحة. ماسك بروبوليس للشفاه يركز على مظهر الجفاف والنعومة، ويمكن أن يكون خطوة خاصة قبل النوم لمن تحتاج شفاهها اهتمامًا إضافيًا.' AND details_json='{"nameAr": "ماسك الشفاه الليلي بالبروبوليس من كوسركس", "tagline": "لحظة تدليل لنعومة الابتسامة.", "benefits": ["إحساس بالترطيب", "ملمس أنعم", "عناية ضمن روتين الليل"], "howToUse": "وزعي على شفاه نظيفة بالطريقة المحددة على العبوة.", "notes": "اختبريه أولًا عند الحساسية من منتجات النحل.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}' AND category='المكياج' AND subcategory='شفاه';
UPDATE products SET description='أغلقي يومكِ بلحظة انتعاش. ابدئي يومك بغسول جل يركز على إزالة شوائب السطح وترك البشرة مهيأة للعناية. يمنحك غود مورنينغ خطوة تنظيف عملية لروتين بسيط، مع تعديل التكرار بحسب احتياج البشرة وإحساسها بعد الغسل.',details_json='{"nameAr":"غسول لو بي إتش غود مورنينغ من كوسركس","tagline":"بداية تنظيف خفيفة ومنعشة.","benefits":["تنظيف شوائب السطح","قوام جل","تهيئة الوجه للمرطب"],"howToUse":"رغّي كمية صغيرة على الوجه المبلل ثم اشطفي جيدًا دون فرك.","notes":"إذا سبب إحساسًا بالشد، قللي التكرار وأكملي بمرطب مناسب.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"cleanser","en":{"name":"COSRX - Low pH Good Morning Gel Cleanser","tagline":"A fresh start, or a gentle end to your day.","description":"COSRX - Low pH Good Morning Gel Cleanser. A fresh start, or a gentle end to your day. Make cleansing the first step of a little time for yourself.","benefits":["A fresh start, or a gentle end to your day.","A dedicated step to coordinate with your existing routine."],"howToUse":"Follow the instructions for this cleanser’s format. Massage gently without rubbing hard, and rinse or wipe off as its label directs.","notes":"Avoid contact with the eyes unless the exact product is labelled for eye makeup removal. Patch test and stop if irritation occurs.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='غسول',updated_at=datetime('now') WHERE id='TS0109' AND description='ابدئي يومك بغسول جل يركز على إزالة شوائب السطح وترك البشرة مهيأة للعناية. يمنحك غود مورنينغ خطوة تنظيف عملية لروتين بسيط، مع تعديل التكرار بحسب احتياج البشرة وإحساسها بعد الغسل.' AND details_json='{"nameAr":"غسول لو بي إتش غود مورنينغ من كوسركس","tagline":"بداية تنظيف خفيفة ومنعشة.","benefits":["تنظيف شوائب السطح","قوام جل","تهيئة الوجه للمرطب"],"howToUse":"رغّي كمية صغيرة على الوجه المبلل ثم اشطفي جيدًا دون فرك.","notes":"إذا سبب إحساسًا بالشد، قللي التكرار وأكملي بمرطب مناسب.","imageType":"photo","collection":"k-beauty","featuredOrder":10