UPDATE products SET description='لحظة لون أو عناية، لكِ وحدكِ. امنحي الشفاه لمسة لامعة تبرز شكلها وتكمل إطلالتك. هذا المستحضر من كوسركس مصمم لإحساس البلامبر ولمظهر أكثر امتلاءً بصريًا، ويحتاج تطبيقًا خفيفًا لأن تجربة الوخز تختلف من شخص لآخر.',details_json='{"nameAr":"غلوس ليب بلامبر من كوسركس","tagline":"لمعة تضيف امتلاءً بصريًا للشفاه.","benefits":["لمعان للشفاه","امتلاء بصري للإطلالة","تكملة لمكياج الشفاه"],"howToUse":"ضعي كمية قليلة على الشفاه فقط بحسب تعليمات العبوة.","notes":"قد يسبب وخزًا؛ لا يستخدم على شفاه متشققة أو متهيجة.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"lips","en":{"name":"COSRX - Refresh AHA BHA Vitamin C Lip Plumper","tagline":"A little moment for your lips.","description":"COSRX - Refresh AHA BHA Vitamin C Lip Plumper. A little moment for your lips. Keep your favourite lip detail close, from an everyday moment to evening plans.","benefits":["A little moment for your lips.","Make the finish your own, one light layer at a time."],"howToUse":"Apply gently to clean lips as directed on the packaging. Start with a little and add more if needed.","notes":"Choose the available colour or version. Do not share lip products, and stop use if irritation occurs.","variantNote":""},"contentVersion":"3.0.0"}',category='المكياج',subcategory='شفاه',updated_at=datetime('now') WHERE id='TS0110' AND description='امنحي الشفاه لمسة لامعة تبرز شكلها وتكمل إطلالتك. هذا المستحضر من كوسركس مصمم لإحساس البلامبر ولمظهر أكثر امتلاءً بصريًا، ويحتاج تطبيقًا خفيفًا لأن تجربة الوخز تختلف من شخص لآخر.' AND details_json='{"nameAr": "غلوس ليب بلامبر من كوسركس", "tagline": "لمعة تضيف امتلاءً بصريًا للشفاه.", "benefits": ["لمعان للشفاه", "امتلاء بصري للإطلالة", "تكملة لمكياج الشفاه"], "howToUse": "ضعي كمية قليلة على الشفاه فقط بحسب تعليمات العبوة.", "notes": "قد يسبب وخزًا؛ لا يستخدم على شفاه متشققة أو متهيجة.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}' AND category='المكياج' AND subcategory='شفاه';
UPDATE products SET description='رشة عناية بين تفاصيل يومكِ. احملي خطوة ترطيب منعشة بحجم صغير من خط 345 ريليف. تجمع صيغة البخاخ سهولة التوزيع مع إحساس العناية، لتناسب حقيبة اليوم أو السفر عندما تحتاج البشرة إلى لمسة إضافية دون روتين طويل.',details_json='{"nameAr":"بخاخ كريم 345 ريليف المصغر من دكتور ألثيا","tagline":"عناية خفيفة تسافر معك.","benefits":["حجم عملي للحقيبة","سهولة التوزيع بالرذاذ","إحساس خفيف بالترطيب"],"howToUse":"رشي بالمسافة والطريقة المحددتين على العبوة مع إغلاق العينين.","notes":"هذه صيغة بخاخ مستقلة عن أنبوب كريم 345 ريليف.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"mist","en":{"name":"Dr. Althea - 345 Relief Cream Mist Mini","tagline":"A little care between the moments of your day.","description":"Dr. Althea - 345 Relief Cream Mist Mini. A little care between the moments of your day. Choose a small moment of beauty that fits the way you like to get ready.","benefits":["A little care between the moments of your day.","A dedicated step to coordinate with your existing routine."],"howToUse":"Close your eyes and mouth and spray gently from the distance specified on the packaging.","notes":"Avoid direct contact with the eyes and do not inhale the spray.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='بخاخ',updated_at=datetime('now') WHERE id='TS0111' AND description='احملي خطوة ترطيب منعشة بحجم صغير من خط 345 ريليف. تجمع صيغة البخاخ سهولة التوزيع مع إحساس العناية، لتناسب حقيبة اليوم أو السفر عندما تحتاج البشرة إلى لمسة إضافية دون روتين طويل.' AND details_json='{"nameAr": "بخاخ كريم 345 ريليف المصغر من دكتور ألثيا", "tagline": "عناية خفيفة تسافر معك.", "benefits": ["حجم عملي للحقيبة", "سهولة التوزيع بالرذاذ", "إحساس خفيف بالترطيب"], "howToUse": "رشي بالمسافة والطريقة المحددتين على العبوة مع إغلاق العينين.", "notes": "هذه صيغة بخاخ مستقلة عن أنبوب كريم 345 ريليف.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}' AND category='البشرة' AND subcategory='بخاخ';
