UPDATE products SET description='لمسة عناية لأكثر تفاصيل وجهكِ رقة. أضيفي إلى روتين إزالة المكياج خطوة مخصصة للعناية بمظهر الرموش. سيروم ماي لاش يمنح الشعيرات إحساسًا بالعناية ويسهل توزيعه بأداته، ليكون مناسبًا لمن تحب الاهتمام بالرموش دون افتراض نتيجة علاجية لطولها.',details_json='{"nameAr":"سيروم ماي لاش للرموش من إيتود","tagline":"عناية يومية بالتفاصيل التي تبرز عينيك.","benefits":["العناية بمظهر الرموش","أداة تطبيق سهلة","تكملة لروتين المساء"],"howToUse":"استخدميه على رموش نظيفة بالطريقة المسموح بها على العبوة دون إدخاله إلى العين.","notes":"حافظي على نظافة الأداة ولا تشاركيها مع الآخرين.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"eye-care","en":{"name":"ETUDE - My Lash Serum","tagline":"A small, careful moment for your eyes.","description":"ETUDE - My Lash Serum. A small, careful moment for your eyes. Choose a small moment of beauty that fits the way you like to get ready.","benefits":["A small, careful moment for your eyes.","A dedicated step to coordinate with your existing routine."],"howToUse":"Use a very small amount in the area indicated on the pack, with gentle application and no pulling.","notes":"Keep out of the eyes. Lash products and eye creams have different directions; follow your exact product’s label.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='العناية بالعين والرموش',updated_at=datetime('now') WHERE id='TS0116' AND description='أضيفي إلى روتين إزالة المكياج خطوة مخصصة للعناية بمظهر الرموش. سيروم ماي لاش يمنح الشعيرات إحساسًا بالعناية ويسهل توزيعه بأداته، ليكون مناسبًا لمن تحب الاهتمام بالرموش دون افتراض نتيجة علاجية لطولها.' AND details_json='{"nameAr": "سيروم ماي لاش للرموش من إيتود", "tagline": "عناية يومية بالتفاصيل التي تبرز عينيك.", "benefits": ["العناية بمظهر الرموش", "أداة تطبيق سهلة", "تكملة لروتين المساء"], "howToUse": "استخدميه على رموش نظيفة بالطريقة المسموح بها على العبوة دون إدخاله إلى العين.", "notes": "حافظي على نظافة الأداة ولا تشاركيها مع الآخرين.", "imageType