UPDATE products SET description='خطوة نهارية تستحق مكانًا في روتينكِ. أكملي روتين الصباح بواقي بيوريفاينغ غرين تي من دكتور ألثيا. يمنحك قوام كريم يسهل توزيعه، ويليق بمن تبحث عن خطوة حماية تندمج مع روتين الترطيب قبل المكياج مع اهتمام بالتجديد أثناء اليوم.',details_json='{"nameAr":"واقي بيوريفاينغ غرين تي من دكتور ألثيا","tagline":"حماية نهارية بإحساس مرطب.","benefits":["حماية نهارية","قوام كريمي","إحساس بالعناية المرطبة"],"howToUse":"وزعي كمية كافية حسب تعليمات العبوة وجددي أثناء التعرض للشمس وبعد السباحة أو التعرق.","notes":"هذه نسخة Purifying Green Tea، وهي مختلفة عن Aqua Glowing من العلامة نفسها.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"sunscreen","en":{"name":"Dr. Althea Purifying Green Tea Sunscreen","tagline":"Make room for a daily sun-care ritual.","description":"Dr. Althea Purifying Green Tea Sunscreen. Make room for a daily sun-care ritual. Give sun care a regular place at the end of your morning skincare, before makeup.","benefits":["Make room for a daily sun-care ritual.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply generously and evenly as the final step of morning skincare, before sun exposure. Reapply as directed, especially after sweating or swimming.","notes":"Check the SPF and directions on your exact pack. Use shade and protective clothing as well; no sunscreen blocks all UV exposure.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='واقي شمس',updated_at=datetime('now') WHERE id='TS0123' AND description='أكملي روتين الصباح بواقي بيوريفاينغ غرين تي من دكتور ألثيا. يمنحك قوام كريم يسهل توزيعه، ويليق بمن تبحث عن خطوة حماية تندمج مع روتين الترطيب قبل المكياج مع اهتمام بالتجديد أثناء اليوم.' AND details_json='{"nameAr": "واقي بيوريفاينغ غرين تي من دكتور ألثيا", "tagline": "حماية نهارية بإحساس مرطب.", "benefits": ["حماية نهارية", "قوام كريمي", "إحساس بالعناية المرطبة"], "howToUse": "وزعي كمية كافية حسب تعليمات العبوة وجددي أثناء التعرض للشمس وبعد السباحة أ