UPDATE products SET description='خطوة نهارية تستحق مكانًا في روتينكِ. أضيفي إلى الصباح واقي أكوا غلوينغ من دكتور ألثيا عندما تفضلين قوامًا ينسجم مع العناية المرطبة. يساعدك على إدخال الحماية ضمن روتين يومي منظم، مع الكمية الكافية وتجديدها خلال التعرض للشمس.',details_json='{"nameAr":"واقي أكوا غلوينغ من دكتور ألثيا","tagline":"حماية نهارية تكمّل الإطلالة الندية.","benefits":["حماية نهارية","إحساس بالعناية المرطبة","تنسيق سهل مع المكياج"],"howToUse":"وزعي وفق تعليمات العبوة وجددي أثناء التعرض للشمس وبعد التعرق أو السباحة.","notes":"هذه نسخة Aqua Glowing، وتختلف عن Purifying Green Tea في التشكيلة.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"sunscreen","en":{"name":"Dr. Althea - Aqua Glowing Sunscreen","tagline":"Make room for a daily sun-care ritual.","description":"Dr. Althea - Aqua Glowing Sunscreen. Make room for a daily sun-care ritual. Give sun care a regular place at the end of your morning skincare, before makeup.","benefits":["Make room for a daily sun-care ritual.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply generously and evenly as the final step of morning skincare, before sun exposure. Reapply as directed, especially after sweating or swimming.","notes":"Check the SPF and directions on your exact pack. Use shade and protective clothing as well; no sunscreen blocks all UV exposure.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='واقي شمس',updated_at=datetime('now') WHERE id='TS0178' AND description='أضيفي إلى الصباح واقي أكوا غلوينغ من دكتور ألثيا عندما تفضلين قوامًا ينسجم مع العناية المرطبة. يساعدك على إدخال الحماية ضمن روتين يومي منظم، مع الكمية الكافية وتجديدها خلال التعرض للشمس.' AND details_json='{"nameAr": "واقي أكوا غلوينغ من دكتور ألثيا", "tagline": "حماية نهارية تكمّل الإطلالة الندية.", "benefits": ["حماية نهارية", "إحساس بالعناية المرطبة", "تنسيق سهل مع المكياج"], "howToUse": "وزعي وفق تعليمات العبوة وجددي أثناء التعرض للشمس وبعد التعرق أو السباحة.",