UPDATE products SET description='خطوة تختارينها على مزاج بشرتكِ. إذا كنتِ تفضلين سيرومًا يضيف العناية دون قوام كريم كثيف، تعرفي إلى أكوا مارين ديب. يركز على إحساس الترطيب وتلطيف مظهر الجفاف، ليكون خطوة سهلة قبل المرطب ضمن روتين صباحي أو مسائي يناسب بشرتك.',details_json='{"nameAr":"سيروم أكوا مارين ديب من دكتور ألثيا","tagline":"ترطيب خفيف بلمسة منعشة.","benefits":["قوام سيروم خفيف","إحساس منعش بالترطيب","تلطيف مظهر الجفاف"],"howToUse":"وزعي كمية صغيرة بعد التنظيف وقبل المرطب وفق إرشادات العبوة.","notes":"أكملي الحماية من الشمس عند استخدامه في روتين النهار.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"serum","en":{"name":"Dr. Althea - Aqua Marine Deep Serum 30 ml","tagline":"A thoughtful step in a routine that is yours.","description":"Dr. Althea - Aqua Marine Deep Serum 30 ml. A thoughtful step in a routine that is yours. Choose this step to suit your own skin and routine, introducing it gradually.","benefits":["A thoughtful step in a routine that is yours.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply a small amount to clean skin as directed on the exact product, then follow with moisturiser. Introduce one new active product at a time.","notes":"Patch test first. Results vary by skin and routine; this product is not a substitute for medical advice.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='سيروم',updated_at=datetime('now') WHERE id='TS0188' AND description='إذا كنتِ تفضلين سيرومًا يضيف العناية دون قوام كريم كثيف، تعرفي إلى أكوا مارين ديب. يركز على إحساس الترطيب وتلطيف مظهر الجفاف، ليكون خطوة سهلة قبل المرطب ضمن روتين صباحي أو مسائي يناسب بشرتك.' AND details_json='{"nameAr": "سيروم أكوا مارين ديب من دكتور ألثيا", "tagline": "ترطيب خفيف بلمسة منعشة.", "benefits": ["قوام سيروم خفيف", "إحساس منعش بالترطيب", "تلطيف مظهر الجفاف"], "howToUse": "وزعي كمية صغيرة بعد التنظيف وقبل المرطب وفق إرشادات العبوة.", "notes": "أكملي الحماية من الشمس عند استخدامه في روتين النهار.",