UPDATE products SET description='خطوة تختارينها على مزاج بشرتكِ. سيروم ريتينول B3 من لاروش بوزيه بعبوة 30 مل يرافق روتين العناية المسائي. ابدئي بالتدرج مع الترطيب، وامنحي بشرتكِ وقتًا للتأقلم؛ استخدمي واقي الشمس صباحًا وتجنبي الجمع العشوائي مع المقشرات.',details_json='{"nameAr":"سيروم ريتينول B3 من لاروش بوزيه","tagline":"وقت المساء، ولحظة عناية مدروسة.","benefits":["سيروم ريتينول للعناية المسائية","إدخال تدريجي للروتين","عبوة 30 مل"],"howToUse":"مساءً، وزعي 3–4 قطرات على الوجه والرقبة بعيدًا عن العينين. ابدئي بوتيرة قليلة وأكملي بالمرطب؛ استخدمي واقي الشمس صباحًا.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. يحتوي على ريتينويد؛ يُتجنب أثناء الحمل والرضاعة، مع واقي شمس صباحًا واستشارة المختص عند الحاجة.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"serum","size":"30 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false,"en":{"name":"La Roche-Posay · Retinol B3 Serum","tagline":"A thoughtful step in a routine that is yours.","description":"La Roche-Posay · Retinol B3 Serum. A thoughtful step in a routine that is yours. Choose this step to suit your own skin and routine, introducing it gradually.","benefits":["A thoughtful step in a routine that is yours.","A dedicated step to coordinate with your existing routine."],"howToUse":"Apply a small amount to clean skin as directed on the exact product, then follow with moisturiser. Introduce one new active product at a time.","notes":"Patch test first. Results vary by skin and routine; this product is not a substitute for medical advice. Introduce gradually and follow the exact retinoid directions. Check suitability with a qualified professional if pregnant or breastfeeding.","variantNote":""},"contentVersion":"3.0.0"}',category='البشرة',subcategory='السيروم',updated_at=datetime('now') WHERE id='TS0348' AND description='سيروم ريتينول B3 من لاروش بوزيه بعبوة 30